test("prints a coupon notice as the last line", () => {
  const catalog = createCatalog([
    { sku: "KAFFEE", name: "Kaffeebohnen 500g", priceCents: 1250, vat: "reduced" },
  ]);
  const receipt = checkout(
    [{ sku: "KAFFEE", qty: 3 }],
    catalog,
    [{ code: "ZEHN50", kind: "percent", percent: 10, minSubtotalCents: 5000 }],
    "ZEHN50",
  );
  const lines = renderReceipt(receipt).split("\n");
  expect(lines.at(-1)).toBe("Coupon ZEHN50 requires a minimum order of CHF 50.00");
});
EOF
